// ─── Function application ───────────────────────────────────────────────

/// Arc 233 Stone 233.2.k — apply a TrackedValue callee, preserving provenance
/// in NotCallable errors. Used by eval_list Symbol + List head paths where the
/// callee is looked up or evaluated as a TrackedValue (so producer info flows
/// to the error site intact via ValueSnapshot::of_tracked).
fn apply_tracked_callee(
    callee_tv: TrackedValue,
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
) -> Result<TrackedValue, EvalBreak> {
    let func = match callee_tv.value() {
        Value::wat__core__fn(f) => f.clone(),
        _ => {
            return Err(RuntimeError::new(
                crate::rust_caller_span!(),
                RuntimeErrorKind::NotCallable {
                    got: Box::new(ValueSnapshot::of_tracked(&callee_tv)),
                },
            )
            .into())
        }
    };
    let vals = args
        .iter()
        .map(|a| eval_inner(a, env, sym).map(|tv| tv.value_owned()))
        .collect::<Result<Vec<_>, _>>()?;
    apply_function(func, vals, sym, crate::rust_caller_span!())
        .map(TrackedValue::from)
        .map_err(EvalBreak::from)
}

fn apply_value(
    callee: &Value,
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
) -> Result<Value, EvalBreak> {
    let func = match callee {
        Value::wat__core__fn(f) => f.clone(),
        other => {
            // arc 138: no span — apply_value receives a Value not a WatAST; callee span not in scope
            return Err(RuntimeError::new(
                crate::rust_caller_span!(),
                RuntimeErrorKind::NotCallable {
                    got: Box::new(ValueSnapshot::of(other)),
                },
            )
            .into());
        }
    };
    let vals = args
        .iter()
        .map(|a| eval_inner(a, env, sym).map(|tv| tv.value_owned()))
        .collect::<Result<Vec<_>, _>>()?;
    apply_function(func, vals, sym, crate::rust_caller_span!()).map_err(EvalBreak::from)
}

/// Apply a function to a list of argument values, evaluated under the
/// given symbol table. Arity must match the function's declared
/// parameters; mismatch returns [`RuntimeError::ArityMismatch`].
///
/// Public so the freeze module's `:user::main` invocation and
/// constrained-eval paths can apply pre-registered functions from a
/// frozen world without duplicating the param-binding logic.
///
/// ## Tail-call trampoline (TCO, Stage 1 — named defines)
///
/// The body runs inside a loop that catches
/// [`EvalSignal::TailCall`] (wrapped in [`EvalBreak::Signal`]). When `eval_tail` recognizes a
/// user-defined function call in tail position it emits `TailCall`
/// carrying the next function and its already-evaluated args; this
/// loop reassigns `cur_func`/`cur_args` and re-iterates without
/// recursing. Rust stack stays constant across arbitrary
/// tail-recursion depth (`Console/loop`, `Cache/loop-step`, any
/// `gen_server`-shaped driver). See
/// `docs/arc/2026/04/003-tail-call-optimization/DESIGN.md` for the
/// full treatment.
///
/// Fn self-tail-calls still consume stack in Stage 1 — the
/// evaluator's user-function-call detection keys on
/// `sym.functions`, which holds named defines only. A fn body
/// that tail-calls a *named* define IS covered: the signal fires
/// at the named call, this loop catches it exactly as it does for
/// a define calling itself. Stage 2 extends detection to
/// fn-valued calls.
pub fn apply_function(
    func: Arc<Function>,
    args: Vec<Value>,
    sym: &SymbolTable,
    call_span: Span,
) -> Result<Value, RuntimeError> {
    let mut cur_func = func;
    let mut cur_args = args;
    let mut cur_span = call_span;

    // Arc 016 slice 2: push a frame onto the wat call stack for this
    // invocation. The guard pops on drop — any exit path (Ok, Err,
    // panic) cleans up the frame. Tail calls REPLACE the top frame
    // in place (the current call is substituted by the next callee
    // at the same stack depth), matching what a user reads as
    // "recursion without stack growth."
    // Stone 255.1a — helper: display name for a function without a registered name.
    // Wat fns use their body span; Native builtins should never reach fn-apply
    // without a name (they are always named keywords in sym.functions).
    let fn_display_name = |f: &Function| -> String {
        match &f.body {
            // Arc 109 — an anonymous fn's identity is the structured
            // ANON_FN_SYMBOL marker (becomes the Frame's `symbol`), NOT a
            // `<fn@span>` stringy costume; the location travels structurally via
            // the Frame's file/line (the call_span) / `:at`, not the name.
            FunctionBody::Wat(_) => crate::value::ANON_FN_SYMBOL.to_string(),
            FunctionBody::Native => "<native>".to_string(),
        }
    };
    let callee_name_initial = match cur_func.name.clone() {
        Some(name) => name,
        None => fn_display_name(&cur_func),
    };
    let _frame_guard = FrameGuard::push(callee_name_initial, cur_span.clone());

    loop {
        let fixed_arity = cur_func.params.len();
        let actual_arity = cur_args.len();
        // Arc 150 — variadic arity: when the callee has a rest-param,
        // accept `actual_arity >= fixed_arity`. The first N args bind
        // positionally; the remainder collect into a Value::Vec bound
        // to `rest_param`. Strict-arity behavior is preserved when
        // `rest_param.is_none()`. Mirrors `expand_macro_call`'s
        // arity check (`src/macros.rs:558-580`).
        match cur_func.rest_param {
            None => {
                if actual_arity != fixed_arity {
                    return Err(RuntimeError::new(
                        cur_span.clone(),
                        RuntimeErrorKind::ArityMismatch {
                            op: match cur_func.name.clone() {
                                Some(name) => name,
                                None => fn_display_name(&cur_func),
                            },
                            expected: fixed_arity,
                            got: actual_arity,
                        },
                    ));
                }
            }
            Some(_) => {
                if actual_arity < fixed_arity {
                    return Err(RuntimeError::new(
                        cur_span.clone(),
                        RuntimeErrorKind::ArityMismatch {
                            op: match cur_func.name.clone() {
                                Some(name) => name,
                                None => fn_display_name(&cur_func),
                            },
                            expected: fixed_arity,
                            got: actual_arity,
                        },
                    ));
                }
            }
        }
        // Build the call env: parent is the closed env (fn) or a
        // fresh root (define — the body resolves global names via sym).
        let parent = cur_func.closed_env.clone().unwrap_or_default();
        let mut builder = parent.child();
        // Bind the first `fixed_arity` args positionally to `params`.
        // `cur_args.drain(..fixed_arity)` empties the front of the Vec
        // and leaves the rest-args (if any) at indices 0..N for the
        // rest-binding pass below.
        let mut drained = cur_args.drain(..);
        for name in cur_func.params.iter() {
            let value = drained.next().expect("arity checked above");
            builder = builder.bind_unknown_span(
                crate::scope::env_key(name).into_owned(),
                TrackedValue::from(value),
            );
        }
        // Arc 150 — collect the remaining args (post-fixed) into a
        // Value::Vec and bind to the rest-name. For zero rest-args the
        // binding is an empty Vec; tests rely on this for the
        // zero-rest-args coverage row.
        if let Some(rest_name) = &cur_func.rest_param {
            let rest: Vec<Value> = drained.collect();
            builder = builder.bind_unknown_span(
                rest_name.clone(),
                TrackedValue::from(Value::Vec(Arc::new(rest))),
            );
        } else {
            // Drop the iterator so cur_args is fully drained even on
            // the strict-arity path. (drain runs to completion on
            // drop; explicit drop here makes the lifecycle obvious.)
            drop(drained);
        }
        let call_env = builder.build();
        // Evaluate the body in tail position. `eval_tail` is the
        // tail-aware sibling of `eval`; it emits `EvalBreak::Signal(EvalSignal::TailCall)`
        // when it meets a user-defined function call at the tail — the
        // match below converts that signal into loop continuation.
        //
        // `TryPropagate` keeps its legacy behavior: wrap in the
        // function's own `Err(e)` return. The type checker guarantees
        // this function's declared return type is `:Result<_,E>`
        // whenever its body contains a `try`, so the wrap is
        // type-correct by construction.
        // Stone 255.1a — Native builtins are intercepted by the runtime dispatch match
        // before reaching apply_function; if a Native body somehow arrives here it is a bug.
        let body_ast = match &cur_func.body {
            FunctionBody::Wat(ast) => ast,
            FunctionBody::Native => unreachable!(
                "native builtin fn-applied — dispatched via the runtime match, not fn-apply"
            ),
        };
        match eval_tail(body_ast, &call_env, sym) {
            Ok(v) => return Ok(v),
            Err(EvalBreak::Signal(EvalSignal::TailCall {
                func: next,
                args: next_args,
                call_span: next_span,
            })) => {
                cur_func = next;
                cur_args = next_args;
                cur_span = next_span;
                // Replace the top frame with the new callee's info —
                // tail calls don't deepen the stack; they substitute.
                let next_name = match cur_func.name.clone() {
                    Some(name) => name,
                    None => fn_display_name(&cur_func),
                };
                replace_top_frame(next_name, cur_span.clone());
                continue;
            }
            Err(EvalBreak::Signal(EvalSignal::TryPropagate(e))) => {
                return Ok(Value::Result(Arc::new(Err(*e))));
            }
            Err(EvalBreak::Signal(EvalSignal::OptionPropagate)) => {
                return Ok(Value::Option(Arc::new(None)));
            }
            Err(EvalBreak::Diagnostic(other)) => return Err(*other),
        }
    }
}

// ─── Wat call-stack for failure-diagnosis (arc 016 slice 2) ─────────
//
// Moved to crate::value::frame (Stone 251.2a). Re-exported below for
// in-module use.

use crate::value::{replace_top_frame, FrameGuard};
use crate::value::{snapshot_call_stack, FrameInfo};

// ─── Seven eval forms ────────────────────────────────────────────────────
//
// Mirror of the six load forms, with one extra on the AST side. Arc 028
// dropped the `:wat::eval::<iface>` interface keyword — each form takes
// its source (AST, inline string, or path) directly:
//
//   (:wat::eval-ast!  <Value::Ast>)
//   (:wat::eval-edn!  <source>)
//   (:wat::eval-file! <path>)
//   (:wat::eval-digest!        <path>   :wat::verify::digest-<algo>
//                                       :wat::verify::<iface> <payload>)
//   (:wat::eval-digest-string! <source> :wat::verify::digest-<algo>
//                                       :wat::verify::<iface> <payload>)
//   (:wat::eval-signed!        <path>   :wat::verify::signed-<algo>
//                                       :wat::verify::<iface> <sig>
//                                       :wat::verify::<iface> <pubkey>)
//   (:wat::eval-signed-string! <source> :wat::verify::signed-<algo>
//                                       :wat::verify::<iface> <sig>
//                                       :wat::verify::<iface> <pubkey>)
//
// `eval-ast!` takes a value that IS a parsed AST (already past any trust
// boundary); the others take EDN source text (inline or via path) with
// optional byte-level (digest) or meaning-level (signed) verification.
//
// The mutation-form refusal (FOUNDATION line 663) runs inside every
// path: an AST that contains a `define` / `defmacro` / `struct` / etc.
// is rejected before anything executes.

// ─── Kernel primitives: stopped / send / recv ───────────────────────────

/// `(:wat::kernel::stopped?)` — nullary predicate; returns the kernel
/// stop flag as a `:bool`. The wat's signal handler sets the flag
/// on SIGINT / SIGTERM; user programs poll it in their loops.
///
/// `?` suffix per the 2026-04-19 naming-convention stance —
/// predicates end in `?`.
pub(crate) fn eval_kernel_stopped(args: &[WatAST], list_span: &Span) -> Result<Value, EvalBreak> {
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: ":wat::kernel::stopped?".into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    Ok(Value::bool(KERNEL_STOPPED.load(Ordering::SeqCst)))
}

/// `(:wat::kernel::call-site)` — nullary; returns the caller's
/// `:wat::kernel::Frame {file, line, symbol}` — the wat equivalent of
/// Ruby's `caller` / Rust's `Location::caller()`.
///
/// A native verb pushes no wat frame of its own (only wat fn-calls push,
/// via `FrameGuard`), so from inside this native verb
/// `snapshot_call_stack().first()` IS the caller's frame — the innermost
/// user call that invoked `(:wat::kernel::call-site)`. Mirrors the
/// mechanism `:wat::kernel::assertion-failed!` uses to find "where the
/// author wrote the assert" (src/assertion.rs).
pub(crate) fn eval_kernel_call_site(args: &[WatAST], list_span: &Span) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::call-site";
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    match snapshot_call_stack().first().cloned() {
        Some(frame) => Ok(value_from_frame_info(frame)),
        // Arc 109 — an empty call stack cannot happen from wat: every wat
        // fn-call pushes a FrameGuard before evaluating its body, and all
        // wat runs inside a fn (there is no top-level `call-site` use in the
        // corpus). The old all-`None` Frame here MASKED that invariant with a
        // fabricated value; now Frame's fields are non-`Option` and a value is
        // always known, so refuse honestly instead — mirroring the sibling
        // `macro-call-site`, which likewise refuses on an empty stack rather
        // than fabricating a frame.
        None => Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::MalformedForm {
                head: OP.into(),
                reason: "`:wat::kernel::call-site` was reached with an empty wat call \
                     stack (no enclosing fn frame). Every wat fn-call pushes a frame \
                     before evaluating its body; `call-site` is only meaningful inside \
                     a fn body, never at the top level."
                    .into(),
            },
        )
        .into()),
    }
}

/// `(:wat::kernel::macro-call-site)` — nullary; the EXPAND-TIME twin of
/// `:wat::kernel::call-site`. Meaningful only inside a macro body: returns
/// the macro INVOCATION's own source span — not the runtime call stack
/// (macro expansion runs before any wat fn-call happens, so `CALL_STACK` is
/// irrelevant here) — as a SPLICEABLE `:wat::kernel::Frame` constructor
/// FORM, `Value::wat__WatAST`, not a `Frame` value. A `Frame` VALUE cannot
/// cross `value_to_watast` (it errors on aggregates), so returning one would
/// make `~(:wat::kernel::macro-call-site)` fail to splice; a FORM round-trips
/// through `value_to_watast`'s `wat__WatAST` arm untouched.
///
/// The span comes from the `MACRO_CALL_SITE` thread-local stack
/// (`src/value/frame.rs`), pushed by `expand_macro_call`
/// (src/macros/expand.rs) for the duration of expanding each macro
/// invocation — read the TOP (innermost currently-expanding invocation;
/// nested macro expansion pushes/pops correctly).
///
/// Arc 278 §4 — DESIGN-telemetry-caller-and-capacity.md §4. Uses the
/// generated POSITIONAL PRIME constructor `:wat::kernel::Frame'` (arc 294
/// item 9a: machinery/generated code uses the prime ctor, never hand-rolled
/// kwargs) — mirrors `eval_struct_to_form`'s ctor-form-building convention.
/// Arc 109 — Frame's fields are non-`Option`, so the ctor form supplies bare
/// `file`/`line`/`symbol` values. `symbol` is the NAME of the macro being
/// expanded (threaded through `MacroCallSiteGuard`): at expand time there is no
/// enclosing runtime fn, but the macro itself is known, so its name is the
/// honest symbol — never absent.
pub(crate) fn eval_kernel_macro_call_site(args: &[WatAST], list_span: &Span) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::macro-call-site";
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    let (call_site, macro_name) = match crate::value::current_macro_call_site() {
        Some(pair) => pair,
        None => {
            return Err(RuntimeError::new(
                list_span.clone(),
                RuntimeErrorKind::MalformedForm {
                    head: OP.into(),
                    reason: "`:wat::kernel::macro-call-site` is only valid inside a macro body / \
                         at expand time (no macro invocation is currently being expanded on \
                         this thread)"
                        .into(),
                },
            )
            .into());
        }
    };
    let span = list_span.clone();
    let form = WatAST::List(
        vec![
            WatAST::Keyword(":wat::kernel::Frame'".into(), span.clone()), // rune:lint(retired-name) — positional constructor idiom: Frame is the record, Frame' builds one
            // Arc 109 — Frame's fields are concrete (non-`Option`); the ctor
            // form supplies bare values, never `(Some …)`/`None` wrappers.
            // file: "<file>"
            WatAST::StringLit((*call_site.file).clone(), span.clone()),
            // line: <line>
            WatAST::IntLit(call_site.line, span.clone()),
            // symbol: "<macro name>" — at expand time there is no enclosing
            // runtime fn, but the macro BEING expanded IS known; its name is
            // the honest symbol (never absent).
            WatAST::StringLit(macro_name, span.clone()),
        ],
        span,
    );
    Ok(Value::wat__WatAST(Arc::new(form)))
}

/// Returns the host parallelism as `i64` — `std::thread::available_parallelism()`,
/// falling back to 1 if the OS refuses to report.
///
/// Single source of truth used by:
/// - `(:wat::program::cpu-count)` — the live nullary verb (Arc 259 S3.2b-i)
/// - `src/freeze.rs` — the program-env seam constructor
/// - `src/kernel/spawn.rs` — the thread-peer env constructor
pub(crate) fn host_cpu_count() -> i64 {
    std::thread::available_parallelism()
        .map(|n| n.get() as i64)
        .unwrap_or(1)
}

/// `(:wat::program::env)` — nullary; returns the calling thread's ambient
/// `:wat::program::Env` record (or subtype).
///
/// Arc 259 — The Forced Hand. The env is installed into the `PROGRAM_ENV`
/// thread-local by `install_program_env` at the post-bootstrap /
/// pre-`:user::main` seam. Returns a clone of the current value, or a
/// clean `MalformedForm` error if no env has been installed (e.g. a test
/// that calls `eval_in_frozen` without calling `install_program_env`).
fn eval_program_env(args: &[WatAST], list_span: &Span) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::program::env";
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    crate::services::current_program_env().ok_or_else(|| {
        RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::MalformedForm {
                head: OP.into(),
                reason: "no program env installed on this thread — call install_program_env \
                         before invoking (:wat::program::env)"
                    .into(),
            },
        )
        .into()
    })
}

/// `(:wat::program::self-peer :S :R)` — returns the calling thread's self-peer
/// (the spawned process child's owner-link as a unified `Peer'<S,R>`).
///
/// Arc 209 C0b.3a-0 / C0b.2e-i-b. The self-peer is installed into the `SELF_PEER`
/// thread-local by `install_self_peer` at the child-only seam
/// `run_forms_as_server_child` (process/verbs.rs), before `:user::main` runs.
/// Root never calls that seam → root gets a clean MalformedForm error.
///
/// The two type-keyword args (:S :R) are checker-only; they are validated to
/// be keywords but not evaluated.  The runtime value is a boxed `Peer` (socket
/// tier) under `PEER_TYPE_PATH`.
fn eval_program_self_peer(args: &[WatAST], list_span: &Span) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::program::self-peer";
    if args.len() != 2 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 2,
                got: args.len(),
            },
        )
        .into());
    }
    for (i, a) in args.iter().enumerate() {
        if !is_type_arg_shaped(a) {
            return Err(RuntimeError::new(
                list_span.clone(),
                RuntimeErrorKind::MalformedForm {
                    head: OP.into(),
                    reason: format!(
                        "argument {} must be a type keyword (e.g. :wat::core::i64)",
                        i
                    ),
                },
            )
            .into());
        }
    }
    crate::services::current_self_peer().ok_or_else(|| {
        RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::MalformedForm {
                head: OP.into(),
                reason: "no self-peer — (:wat::program::self-peer) is only valid inside a spawned \
                     process service; root has no owner-link"
                    .into(),
            },
        )
        .into()
    })
}

/// `(:wat::program::cpu-count)` — nullary; returns the host parallelism as
/// `:wat::core::i64` via [`host_cpu_count`].
///
/// Arc 259 S3.2b-i. Unlike the stamped `cpu-count` env field (reachable only
/// via `(:wat::program::env)` when a program env is installed), this verb answers
/// `std::thread::available_parallelism()` directly — no installed program env
/// required. Mirrors `(:wat::time::now)`: a live host fact available in ANY eval
/// context. Used by the brackets pool to size its default runner count.
fn eval_program_cpu_count(args: &[WatAST], list_span: &Span) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::program::cpu-count";
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    Ok(Value::i64(host_cpu_count()))
}

/// `(:wat::runtime::argv)` — nullary; returns the process-wide argv
/// ambient as `:wat::core::Vector<wat::core::String>`.
///
/// Arc 170 slice 1e (REALIZATIONS pass 7). The four-arg `:user::main`
/// shape (stdin/stdout/stderr/argv) retires; argv moves to ambient.
/// Wat-cli (or any embedder) calls [`crate::runtime::set_argv`]
/// before `:user::main` runs; subsequent reads from any depth in the
/// program return the same Vec. Empty Vec when no embedder set it
/// (in-process tests, library bridges that bypass wat-cli) — the
/// ambient is "always available."
fn eval_runtime_argv(args: &[WatAST], list_span: &Span) -> Result<Value, EvalBreak> {
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: ":wat::runtime::argv".into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    let argv = argv();
    let values: Vec<Value> = argv
        .iter()
        .map(|s| Value::String(Arc::new(s.clone())))
        .collect();
    Ok(Value::Vec(Arc::new(values)))
}

/// `(:wat::runtime::current-thread)` — nullary; returns the calling
/// thread's id as `:wat::core::String`.
///
/// Arc 170 slice 1e (REALIZATIONS pass 7). For slice 1e this is the
/// main thread's representation; slice 1g extends to spawned threads
/// via thread-locals populated at spawn-time. Implemented against
/// `std::thread::current().id()` which is meaningful on every thread
/// the substrate creates today.
fn eval_runtime_current_thread(args: &[WatAST], list_span: &Span) -> Result<Value, EvalBreak> {
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: ":wat::runtime::current-thread".into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    let id = std::thread::current().id();
    Ok(Value::String(Arc::new(format!("{:?}", id))))
}

/// Shared body for the three user-signal predicates — nullary, reads a
/// given atomic flag. `op` is the wat-facing keyword path for error
/// messages.
pub(crate) fn eval_user_signal_query(
    args: &[WatAST],
    op: &str,
    flag: &AtomicBool,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: op.into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    Ok(Value::bool(flag.load(Ordering::SeqCst)))
}

/// Shared body for the three user-signal resetters — nullary, flips a
/// given atomic flag back to `false`. Unlike the terminal stop flag
/// (set-once), user-signal flags are designed to be toggled by userland
/// after the signal's condition has been handled.
pub(crate) fn eval_user_signal_reset(
    args: &[WatAST],
    op: &str,
    flag: &AtomicBool,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: op.into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    flag.store(false, Ordering::SeqCst);
    Ok(Value::Unit)
}

// ─── Config accessors ─────────────────────────────────────────────────
//
// Every setter in `:wat::config::set-*!` commits exactly once during
// the startup's config pass. After freeze, the committed value is read
// by its nullary accessor. These have the same discipline as other
// substrate constants — no arguments, deterministic, safe to call from
// any context as long as the SymbolTable carries an EncodingCtx (which
// it does after freeze).

fn require_encoding_ctx<'a>(
    op: &'static str,
    sym: &'a SymbolTable,
    list_span: &Span,
) -> Result<&'a EncodingCtx, EvalBreak> {
    sym.encoding_ctx().map(|arc| arc.as_ref()).ok_or_else(|| {
        EvalBreak::from(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::NoEncodingCtx { op: op.into() },
        ))
    })
}

/// Arc 077: the program runs at one d. Read it from the ambient
/// `EncodingCtx`. Returns `NoEncodingCtx` if no ctx is attached
/// (test harnesses that bypass freeze).
fn program_dim(op: &'static str, sym: &SymbolTable, list_span: &Span) -> Result<usize, EvalBreak> {
    let ctx = require_encoding_ctx(op, sym, list_span)?;
    Ok(ctx.dim_count)
}

fn check_nullary(op: &'static str, args: &[WatAST], list_span: &Span) -> Result<(), EvalBreak> {
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: op.into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    Ok(())
}

/// `(:wat::config::dim-count)` -> `:i64`. The program's encoding dim,
/// set once at startup via `(:wat::config::set-dim-count! n)`;
/// defaults to [`crate::config::DEFAULT_DIMS`] (10000) when no
/// encoding ctx is attached (test harnesses bypassing the freeze
/// pipeline).
fn eval_config_dim_count(
    args: &[WatAST],
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    check_nullary(":wat::config::dim-count", args, list_span)?;
    match sym.encoding_ctx() {
        Some(ctx) => Ok(Value::i64(ctx.dim_count as i64)),
        None => Ok(Value::i64(crate::config::DEFAULT_DIM_COUNT as i64)),
    }
}

/// `(:wat::config::dim-capacity)` -> `:i64`. Hologram-slot count for
/// this program: `floor(sqrt(dim-count))`. Cached at freeze; reads
/// from `EncodingCtx`. Falls back to the default-derived value when
/// no encoding ctx is attached.
fn eval_config_dim_capacity(
    args: &[WatAST],
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    check_nullary(":wat::config::dim-capacity", args, list_span)?;
    match sym.encoding_ctx() {
        Some(ctx) => Ok(Value::i64(ctx.capacity as i64)),
        None => {
            let d = crate::config::DEFAULT_DIM_COUNT;
            // Arc 294.c.2a — the ONE capacity formula (no recompute).
            let cap = crate::hologram::kanerva_capacity(d);
            Ok(Value::i64(cap as i64))
        }
    }
}

/// `(:wat::config::noise-floor)` — `1/sqrt(dim-count)` at the
/// program's d. Held for legacy callers; per-d noise-floor is also
/// computed internally by presence? / coincident? against the same
/// program-d.
fn eval_config_noise_floor_default_shim(
    args: &[WatAST],
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    check_nullary(":wat::config::noise-floor", args, list_span)?;
    let d = match sym.encoding_ctx() {
        Some(ctx) => ctx.dim_count,
        None => crate::config::DEFAULT_DIM_COUNT,
    };
    Ok(Value::f64(1.0 / (d as f64).sqrt()))
}

/// `(:wat::config::global-seed)` — committed atom-seeding seed as `:i64`.
fn eval_config_global_seed(
    args: &[WatAST],
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    check_nullary(":wat::config::global-seed", args, list_span)?;
    let ctx = require_encoding_ctx(":wat::config::global-seed", sym, list_span)?;
    Ok(Value::i64(ctx.config.global_seed as i64))
}

/// Arc 209 C0b.2c / C0b.2e-i-b / Arc 258.5b-ii — wrap a connected `UnixStream` as a
/// `(:wat::kernel::listener host …)` — Arc 209 Stone C0b.1 / C0b.2c / C0b.2d.
///
/// Thread tier (C0b.1): `(listener' (thread) :S :R)` — mints a crossbeam rendezvous
/// channel and returns `Tuple[Listener'<S,R>, Address'<S,R>]` (raw Receiver / raw Sender).
/// 3 args: host, :S, :R.
///
/// Process tier (C0b.2d → arc 272): `(listener' (process) :S :R)` — autobinds an abstract-namespace
/// UDS (kernel-minted, exclusive-bind, not a chosen name) and returns `Bound{ listener, address }`
/// mirroring the thread tier. 3 args: host, :S, :R. The legacy 2-arg named form (`socket-address'`
/// opaque) was annihilated in arc 272 step 5 (guessable names → squattable; autobind is the only
/// rendezvous). The SO_PEERCRED uid+pid checks are the security; the autobind name is an
/// exclusive-bind rendezvous token, not a secret.
///
/// The host value (args[0]) is evaluated at runtime to dispatch between tiers; arity is
/// validated AFTER host dispatch (thread=3, process=2).
pub(crate) fn eval_listener_prime(
    args: &[WatAST],
    list_span: &Span,
    env: &Environment,
    sym: &SymbolTable,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::listener";
    // Need at least the host arg to dispatch.
    if args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 2,
                got: 0,
            },
        )
        .into());
    }
    // Evaluate the host to dispatch between thread and process tiers.
    let host_val = eval_inner(&args[0], env, sym)?.value_owned();
    let is_process = matches!(&host_val,
        Value::Aggregate(a) if a.class.as_ref() == "wat::spawn::ProcessOpts");

    if is_process {
        // Arc 272 — 3-arg AUTOBIND form `(listener' (process) :S :R)`: mint a kernel-unique,
        // exclusive-bind abstract address (kernel-minted, not a chosen name → no collision, no
        // squatting) and return `Bound<S,R>{listener, address}`, MIRRORING the thread tier.
        // The address is the capability `connect'` dials. (The 2-arg `(host addr)` named form
        // below is LEGACY — annihilated in arc 272 step 5 with the rest of the name-discovery
        // stack.) The SO_PEERCRED uid+pid checks are the security; the autobind name is the
        // exclusive-bind rendezvous token, not a secret.
        // Arc 278 Stone 1 — the process form accepts an OPTIONAL 4th arg: the
        // service's declared hard frame limit `FOO` (bytes-per-read), threaded to
        // the accepted-connection receivers via `SocketListener`. 3 args → default
        // `DEFAULT_MAX_FRAME_BYTES` (512 KiB); 4 args → the declared `FOO`.
        if args.len() == 3 || args.len() == 4 {
            for i in [1usize, 2usize] {
                if !is_type_arg_shaped(&args[i]) {
                    return Err(RuntimeError::new(
                        args[i].span().clone(),
                        RuntimeErrorKind::MalformedForm {
                            head: OP.into(),
                            reason: format!(
                                "argument {} must be a type keyword (e.g. :wat::core::i64)",
                                i
                            ),
                        },
                    )
                    .into());
                }
            }
            // Evaluate the optional per-service frame budget `FOO` (arg 3).
            let max_frame_bytes: usize = if args.len() == 4 {
                match eval_inner(&args[3], env, sym)?.value_owned() {
                    Value::i64(n) if n > 0 => n as usize,
                    other => {
                        return Err(RuntimeError::new(args[3].span().clone(), RuntimeErrorKind::MalformedForm {
                                head: OP.into(),
                                reason: format!(
                                    "argument 3 (:max-frame-bytes FOO) must be a positive i64; got {:?}",
                                    other.type_name()
                                ),
                            })
                        .into());
                    }
                }
            } else {
                crate::edn_shim::DEFAULT_MAX_FRAME_BYTES
            };
            // autobind_listener creates the socket SOCK_NONBLOCK (the C0b.3a-i invariant).
            let (ul, name_bytes) = crate::comms::process::autobind_listener(128).map_err(|e| {
                RuntimeError::new(
                    list_span.clone(),
                    RuntimeErrorKind::MalformedForm {
                        head: OP.into(),
                        reason: format!("autobind UDS listener: {}", e),
                    },
                )
            })?;
            use crate::kernel::address::Address;
            use crate::kernel::listener::Listener;
            use crate::kernel::spawn::{ADDRESS_TYPE_PATH, LISTENER_TYPE_PATH};
            use crate::rust_deps::marshal::make_rust_opaque;
            // Arc 272 6c.2 — stamp the minter pid at autobind so the connect gate can verify the
            // kernel-vouched answerer pid against it. SAFETY: getpid() is always-succeeds, no args.
            let minter_pid = unsafe { libc::getpid() };
            return Ok(Value::Aggregate(Arc::new(AggregateValue::struct_(
                "wat::spawn::Bound".into(),
                bound_names(),
                vec![
                    make_rust_opaque(
                        LISTENER_TYPE_PATH,
                        Listener::from_socket(ul, max_frame_bytes),
                    ),
                    make_rust_opaque(
                        ADDRESS_TYPE_PATH,
                        Address::from_socket_name_bytes(name_bytes, minter_pid),
                    ),
                ],
            ))));
        }
        // Arc 272 step 5 — the process listener is AUTOBIND-ONLY. The legacy 2-arg named form
        // `(listener' (process) <socket-address'>)` is ANNIHILATED with the rest of the
        // name-discovery stack: a chosen name is guessable hence squattable, so all rendezvous is
        // the kernel-minted exclusive-bind autobind capability (the 3-arg form above), handed
        // over the lineage channel. Anything but the 3-arg autobind form is an arity error.
        Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 3,
                got: args.len(),
            },
        )
        .into())
    } else {
        // Thread tier (C0b.1): 3 args — host, :S, :R.
        if args.len() != 3 {
            return Err(RuntimeError::new(
                list_span.clone(),
                RuntimeErrorKind::ArityMismatch {
                    op: OP.into(),
                    expected: 3,
                    got: args.len(),
                },
            )
            .into());
        }
        // Validate args[1] and args[2] are type keywords (args[0] is the host expression).
        for i in [1usize, 2usize] {
            if !is_type_arg_shaped(&args[i]) {
                return Err(RuntimeError::new(
                    args[i].span().clone(),
                    RuntimeErrorKind::MalformedForm {
                        head: OP.into(),
                        reason: format!(
                            "argument {} must be a type keyword (e.g. :wat::core::i64)",
                            i
                        ),
                    },
                )
                .into());
            }
        }
        // Mint the crossbeam rendezvous channel.
        // Listener' = rx (the service accept-side, wrapped as Listener entity);
        // Address' = tx (the client dial-side, wrapped as Address entity — C0b.2e-iii).
        let (tx, rx) = crate::comms::thread::pair::<Value>();
        // Arc 209 C0b.2e-ii — wrap rx as the unified Listener entity.
        // Arc 209 C0b.2e-iii — wrap tx as the unified Address entity (was raw Sender).
        use crate::kernel::address::Address;
        use crate::kernel::listener::Listener;
        use crate::kernel::spawn::{ADDRESS_TYPE_PATH, LISTENER_TYPE_PATH};
        use crate::rust_deps::marshal::make_rust_opaque;
        Ok(Value::Aggregate(Arc::new(AggregateValue::struct_(
            "wat::spawn::Bound".into(),
            bound_names(),
            vec![
                make_rust_opaque(LISTENER_TYPE_PATH, Listener::from_crossbeam(rx)),
                make_rust_opaque(ADDRESS_TYPE_PATH, Address::from_thread(tx)),
            ],
        ))))
    }
}

::wat_source_derive::wat_field_names_from!(
    BOUND_FIELDS,
    "wat/spawn.wat",
    ":wat::spawn::Bound"
);
fn bound_names() -> Arc<Vec<String>> {
    static N: std::sync::OnceLock<Arc<Vec<String>>> = std::sync::OnceLock::new();
    N.get_or_init(|| crate::value::value::names_arc_from_static(BOUND_FIELDS))
        .clone()
}

/// `(:wat::kernel::connect addr)` — Arc 209 Stone C0b.1 / C0b.2c / C0b.2e-iii.
///
/// Arc 209 C0b.2e-iii: `addr` is now a unified `Address'` opaque (both thread and
/// process tiers). Downcasts the opaque to `Address`, calls `inner.connect(sym, span)`,
/// wraps the returned `Peer` as a `PEER_TYPE_PATH` opaque.  One arm, two impls.
///
/// (Formerly two arms: thread tier dispatched on `Value::wat__kernel__Sender`;
/// process tier dispatched on `SOCKET_ADDRESS_TYPE_PATH`. Both bodies moved verbatim
/// into `ThreadAddress::connect` / `SocketAddress::connect` in `kernel/address.rs`.)
pub(crate) fn eval_connect_prime(
    args: &[WatAST],
    list_span: &Span,
    env: &Environment,
    sym: &SymbolTable,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::connect";
    if args.len() != 1 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 1,
                got: args.len(),
            },
        )
        .into());
    }
    let addr_val = eval_inner(&args[0], env, sym)?.value_owned();
    // Arc 209 C0b.2e-iii — one arm: downcast the Address' opaque → inner.connect.
    let addr: &crate::kernel::address::Address = match addr_val {
        Value::RustOpaque(ref inner)
            if inner.type_path == crate::kernel::spawn::ADDRESS_TYPE_PATH =>
        {
            use crate::rust_deps::marshal::downcast_ref_opaque;
            downcast_ref_opaque(
                inner.as_ref(),
                crate::kernel::spawn::ADDRESS_TYPE_PATH,
                OP,
                args[0].span().clone(),
            )?
        }
        ref other => {
            return Err(RuntimeError::new(
                args[0].span().clone(),
                RuntimeErrorKind::TypeMismatch {
                    op: OP.into(),
                    expected: "Address<S,R>",
                    got: Box::new(ValueSnapshot::of(other)),
                },
            )
            .into());
        }
    };
    addr.connect_as_value(sym, list_span)
}

/// Unpack a connect-request `Value` and wrap the server `Peer'` end on the
/// current thread.
///
/// Called by both `eval_accept_prime` (after a blocking `typed_recv` on the
/// listener) and by the 2-arg `eval_peer_select_prime` (after the listener
/// arm of `sel.select()` fires).  ONE helper, TWO callers — the wrap logic
/// is not duplicated.
///
/// The connect-request is a `Value::Tuple` `(req_rx: Receiver, resp_tx: Sender)`
/// minted by `connect'` and uniquely owned at the point of receipt:
/// `Arc::try_unwrap` succeeds.  Returns the server `Peer'<R,S>` opaque.
fn wrap_connect_request(cr: Value, span: &Span) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::accept"; // same context for error messages
                                             // Unpack the connect-request tuple: (req_rx: Receiver, resp_tx: Sender).
    let mut items: Vec<Value> = match cr {
        Value::Tuple(arc) => match Arc::try_unwrap(arc) {
            Ok(vec) => vec,
            Err(arc) => (*arc).clone(),
        },
        other => {
            return Err(RuntimeError::new(
                span.clone(),
                RuntimeErrorKind::MalformedForm {
                    head: OP.into(),
                    reason: format!(
                        "connect-request must be a Tuple; got {:?}",
                        other.type_name()
                    ),
                },
            )
            .into());
        }
    };
    if items.len() != 2 {
        return Err(RuntimeError::new(
            span.clone(),
            RuntimeErrorKind::MalformedForm {
                head: OP.into(),
                reason: format!(
                    "connect-request tuple must have 2 elements; got {}",
                    items.len()
                ),
            },
        )
        .into());
    }
    // Move items out in reverse order so indices stay valid.
    let resp_tx_val = items.remove(1);
    let req_rx_val = items.remove(0);
    // Extract req_rx (Receiver<Value>) — moved out, unique owner.
    let req_rx = match req_rx_val {
        Value::wat__kernel__Receiver(arc) => match Arc::try_unwrap(arc) {
            Ok(crate::channel::ReceiverInner::Comms(rx)) => rx,
            Ok(_) => {
                return Err(RuntimeError::new(
                    span.clone(),
                    RuntimeErrorKind::MalformedForm {
                        head: OP.into(),
                        reason: "connect-request rx is not a comms (thread-tier) receiver".into(),
                    },
                )
                .into());
            }
            Err(_) => {
                return Err(RuntimeError::new(
                    span.clone(),
                    RuntimeErrorKind::MalformedForm {
                        head: OP.into(),
                        reason: "connect-request rx has unexpected additional references".into(),
                    },
                )
                .into());
            }
        },
        other => {
            return Err(RuntimeError::new(
                span.clone(),
                RuntimeErrorKind::TypeMismatch {
                    op: OP.into(),
                    expected: "Receiver (connect-request req_rx)",
                    got: Box::new(ValueSnapshot::of(&other)),
                },
            )
            .into());
        }
    };
    // Extract resp_tx (Sender<Value>) — moved out, unique owner.
    let resp_tx = match resp_tx_val {
        Value::wat__kernel__Sender(arc) => match Arc::try_unwrap(arc) {
            Ok(crate::channel::SenderInner::Comms { sender, .. }) => sender,
            Err(_) => {
                return Err(RuntimeError::new(
                    span.clone(),
                    RuntimeErrorKind::MalformedForm {
                        head: OP.into(),
                        reason: "connect-request tx has unexpected additional references".into(),
                    },
                )
                .into());
            }
        },
        other => {
            return Err(RuntimeError::new(
                span.clone(),
                RuntimeErrorKind::TypeMismatch {
                    op: OP.into(),
                    expected: "Sender (connect-request resp_tx)",
                    got: Box::new(ValueSnapshot::of(&other)),
                },
            )
            .into());
        }
    };
    // Wrap the server Peer'<R,S> end on THIS thread (custody holds).
    use crate::kernel::peer::Peer;
    use crate::kernel::spawn::PEER_TYPE_PATH;
    use crate::rust_deps::custodia::ThreadOwnedCell;
    use crate::rust_deps::marshal::make_rust_opaque;
    Ok(make_rust_opaque(
        PEER_TYPE_PATH,
        Arc::new(ThreadOwnedCell::new(Some(Peer::from_thread(
            resp_tx, req_rx,
        )))),
    ))
}

/// `(:wat::kernel::accept listener)` — Arc 209 Stone C0b.1 / C0b.2c.
///
/// Thread tier (C0b.1): block on the rendezvous `Listener'` (a raw
/// `Receiver`) until a connect-request arrives; unpack the server's raw
/// halves `(req_rx, resp_tx)`; wrap the server `Peer'<R,S>` end on THIS
/// thread (custody holds).  Returns the server `Peer'`.
///
/// Process tier (C0b.2c): downcast the `SocketListener'` opaque to
/// `&UnixListener`, call `.accept()` (blocks until a connection — the
/// honest wire-wait), wrap the accepted stream as a unified `Peer'<R,S>`.
/// Returns `Peer'<R,S>`.
pub(crate) fn eval_accept_prime(
    args: &[WatAST],
    list_span: &Span,
    env: &Environment,
    sym: &SymbolTable,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::accept";
    if args.len() != 1 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 1,
                got: args.len(),
            },
        )
        .into());
    }
    let listener_val = eval_inner(&args[0], env, sym)?.value_owned();
    // Arc 209 C0b.2e-ii — ONE arm: downcast the unified Listener entity.
    match listener_val {
        Value::RustOpaque(ref inner)
            if inner.type_path == crate::kernel::spawn::LISTENER_TYPE_PATH =>
        {
            use crate::kernel::listener::Listener;
            use crate::rust_deps::marshal::downcast_ref_opaque;
            let listener: &Listener = downcast_ref_opaque(
                inner.as_ref(),
                crate::kernel::spawn::LISTENER_TYPE_PATH,
                OP,
                args[0].span().clone(),
            )?;
            listener.accept_as_value(sym, list_span)
        }
        other => Err(RuntimeError::new(
            args[0].span().clone(),
            RuntimeErrorKind::TypeMismatch {
                op: OP.into(),
                expected: "Listener<S,R> (unified Listener entity from listener)",
                got: Box::new(ValueSnapshot::of(&other)),
            },
        )
        .into()),
    }
}

/// Arc 209 C0b.3b-b — `(:wat::kernel::allow listener pid)` → `nil`.
///
/// Inserts `pid` into the `SocketListener`'s allow-set. Process-tier only: a
/// `CrossbeamListener` has no allow-set (the crossbeam handle IS the grant).
pub(crate) fn eval_allow_prime(
    args: &[WatAST],
    list_span: &Span,
    env: &Environment,
    sym: &SymbolTable,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::allow";
    if args.len() != 2 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 2,
                got: args.len(),
            },
        )
        .into());
    }
    let listener_val = eval_inner(&args[0], env, sym)?.value_owned();
    match listener_val {
        Value::RustOpaque(ref inner)
            if inner.type_path == crate::kernel::spawn::LISTENER_TYPE_PATH =>
        {
            use crate::kernel::listener::{Listener, SocketListener};
            use crate::rust_deps::marshal::downcast_ref_opaque;
            let listener: &Listener = downcast_ref_opaque(
                inner.as_ref(),
                crate::kernel::spawn::LISTENER_TYPE_PATH,
                OP,
                args[0].span().clone(),
            )?;
            match listener.inner.as_any_ref().downcast_ref::<SocketListener>() {
                Some(sl) => {
                    let pid_val = eval_inner(&args[1], env, sym)?.value_owned();
                    let pid = match pid_val {
                        Value::i64(n) => n as i32,
                        other => {
                            return Err(RuntimeError::new(
                                args[1].span().clone(),
                                RuntimeErrorKind::TypeMismatch {
                                    op: OP.into(),
                                    expected: "i64 (pid)",
                                    got: Box::new(ValueSnapshot::of(&other)),
                                },
                            )
                            .into());
                        }
                    };
                    sl.allow(pid, list_span.clone())?;
                    Ok(Value::Unit)
                }
                None => Err(RuntimeError::new(
                    args[0].span().clone(),
                    RuntimeErrorKind::MalformedForm {
                        head: OP.into(),
                        reason: "allow is a process-tier service gate; \
                                 a thread listener's handle IS the grant"
                            .into(),
                    },
                )
                .into()),
            }
        }
        other => Err(RuntimeError::new(
            args[0].span().clone(),
            RuntimeErrorKind::TypeMismatch {
                op: OP.into(),
                expected: "Listener<S,R> (unified Listener entity from listener)",
                got: Box::new(ValueSnapshot::of(&other)),
            },
        )
        .into()),
    }
}

