/// Shared implementation for the unary stdlib math calls —
/// `:wat::std::math::ln`, `log`, `sin`, `cos`. Arity 1. Argument must
/// evaluate to `:f64` (or `:i64` auto-promoted). `op_name` is the
/// wat-facing short name for error messages.
fn eval_math_unary(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    op_name: &str,
    f: fn(f64) -> f64,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    if args.len() != 1 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: format!(":wat::std::math::{}", op_name),
                expected: 1,
                got: args.len(),
            },
        )
        .into());
    }
    let x = match eval_inner(&args[0], env, sym)?.value_owned() {
        Value::f64(x) => x,
        Value::i64(n) => n as f64,
        other => {
            return Err(RuntimeError::new(
                args[0].span().clone(),
                RuntimeErrorKind::TypeMismatch {
                    op: format!(":wat::std::math::{}", op_name),
                    expected: "f64",
                    got: Box::new(ValueSnapshot::of(&other)),
                },
            )
            .into());
        }
    };
    Ok(Value::f64(f(x)))
}

/// `(:wat::std::math::pi)` — the mathematical constant π as `:f64`.
/// Nullary. Backing: `std::f64::consts::PI`.
fn eval_math_pi(args: &[WatAST], list_span: &Span) -> Result<Value, EvalBreak> {
    if !args.is_empty() {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: ":wat::std::math::pi".into(),
                expected: 0,
                got: args.len(),
            },
        )
        .into());
    }
    Ok(Value::f64(std::f64::consts::PI))
}

/// `(:wat::std::stat::mean :wat::core::Vector<f64>) -> :wat::core::Option<f64>`. Population
/// mean. None on empty input — matches `f64::min-of`/`max-of`'s
/// reduction-empty convention.
///
/// Surfaced by holon-lab-trading arc 026 slice 9 (Hurst's R/S
/// analysis) and slice 4 (Bollinger's RollingStddev). Universal
/// enough to live in core stdlib.
fn eval_stat_mean(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::std::stat::mean";
    if args.len() != 1 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 1,
                got: args.len(),
            },
        )
        .into());
    }
    let xs = require_vec(OP, eval_inner(&args[0], env, sym)?.value_owned())?;
    if xs.is_empty() {
        return Ok(Value::Option(Arc::new(None)));
    }
    let mut sum = 0.0;
    for v in xs.iter() {
        match v {
            Value::f64(x) => sum += x,
            other => {
                return Err(RuntimeError::new(
                    args[0].span().clone(),
                    RuntimeErrorKind::TypeMismatch {
                        op: OP.into(),
                        expected: "Vec<f64>",
                        got: Box::new(ValueSnapshot::of(other)),
                        // arc 138: no — iterating over Vec<Value>; no per-element AST span
                    },
                )
                .into());
            }
        }
    }
    Ok(Value::Option(Arc::new(Some(Value::f64(
        sum / xs.len() as f64,
    )))))
}

/// `(:wat::std::stat::variance :wat::core::Vector<f64>) -> :wat::core::Option<f64>`. Population
/// variance (divides by n). Matches numpy default `ddof=0`. None on
/// empty input. Single-point input returns `Some(0.0)` (no spread).
fn eval_stat_variance(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::std::stat::variance";
    if args.len() != 1 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 1,
                got: args.len(),
            },
        )
        .into());
    }
    let xs = require_vec(OP, eval_inner(&args[0], env, sym)?.value_owned())?;
    if xs.is_empty() {
        return Ok(Value::Option(Arc::new(None)));
    }
    let n = xs.len() as f64;
    let mut sum = 0.0;
    for v in xs.iter() {
        match v {
            Value::f64(x) => sum += x,
            other => {
                return Err(RuntimeError::new(
                    args[0].span().clone(),
                    RuntimeErrorKind::TypeMismatch {
                        op: OP.into(),
                        expected: "Vec<f64>",
                        got: Box::new(ValueSnapshot::of(other)),
                        // arc 138: no — iterating over Vec<Value>; no per-element AST span
                    },
                )
                .into());
            }
        }
    }
    let mean = sum / n;
    let mut sq = 0.0;
    for v in xs.iter() {
        if let Value::f64(x) = v {
            let dx = x - mean;
            sq += dx * dx;
        }
    }
    Ok(Value::Option(Arc::new(Some(Value::f64(sq / n)))))
}

/// `(:wat::std::stat::stddev :wat::core::Vector<f64>) -> :wat::core::Option<f64>`. Square
/// root of population variance.
fn eval_stat_stddev(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::std::stat::stddev";
    if args.len() != 1 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: OP.into(),
                expected: 1,
                got: args.len(),
            },
        )
        .into());
    }
    match eval_stat_variance(args, env, sym, list_span)? {
        Value::Option(opt) => match &*opt {
            Some(Value::f64(var)) => Ok(Value::Option(Arc::new(Some(Value::f64(var.sqrt()))))),
            Some(_) => unreachable!("variance returned a non-f64 inside Option"),
            None => Ok(Value::Option(Arc::new(None))),
        },
        other => Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::TypeMismatch {
                op: OP.into(),
                expected: "Option<f64> from inner variance",
                got: Box::new(ValueSnapshot::of(&other)),
                // arc 138: no — internal variance re-wrap; no originating AST element
            },
        )
        .into()),
    }
}

/// `(:wat::kernel::HandlePool::new name handles)` — build a pool of
/// N handles of the same type. `name` surfaces in error messages; the
/// pool drains as callers `pop` and asserts empty at `finish`.
///
/// Implementation: a bounded crossbeam channel of size N pre-filled
/// with the given handles, whose sender is dropped immediately so
/// further puts are impossible. Consumers `pop` via `recv` (the sender
/// is already gone so recv returns immediately on empty); `finish`
/// checks the channel is empty. No Mutex; the channel's
/// lock-free multi-consumer semantics are the synchronization.
pub(crate) fn eval_handle_pool_new(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    if args.len() != 2 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: ":wat::kernel::HandlePool::new".into(),
                expected: 2,
                got: args.len(),
            },
        )
        .into());
    }
    let name = match eval_inner(&args[0], env, sym)?.value_owned() {
        Value::String(s) => s,
        other => {
            return Err(RuntimeError::new(
                args[0].span().clone(),
                RuntimeErrorKind::TypeMismatch {
                    op: ":wat::kernel::HandlePool::new".into(),
                    expected: "String",
                    got: Box::new(ValueSnapshot::of(&other)),
                },
            )
            .into());
        }
    };
    let handles = match eval_inner(&args[1], env, sym)?.value_owned() {
        Value::Vec(v) => v,
        other => {
            return Err(RuntimeError::new(
                args[1].span().clone(),
                RuntimeErrorKind::TypeMismatch {
                    op: ":wat::kernel::HandlePool::new".into(),
                    expected: "wat::core::Vector",
                    got: Box::new(ValueSnapshot::of(&other)),
                },
            )
            .into());
        }
    };
    let n = handles.len();
    // Zero-handle pools are legal — a pool with zero handles whose
    // `finish` is called immediately asserts true vacuously. Callers
    // that pre-count capacity may hit N=0 for degenerate cases.
    let (tx, rx) = crossbeam_channel::bounded::<Value>(n.max(1));
    for v in handles.iter() {
        if tx.send(v.clone()).is_err() {
            // The rx is local to this scope; send cannot fail.
            unreachable!("newly-built channel receiver must be alive");
        }
    }
    // Drop tx so the channel's is_empty discipline reads "fully
    // drained" once every handle is popped.
    drop(tx);
    Ok(Value::wat__kernel__HandlePool {
        name,
        rx: Arc::new(rx),
    })
}

/// `(:wat::kernel::HandlePool::pop pool)` — claim one handle. Returns
/// the claimed value. If the pool is empty, returns a
/// MalformedForm error naming the pool — callers are expected to
/// pop exactly the count they committed to at construction.
pub(crate) fn eval_handle_pool_pop(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    if args.len() != 1 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: ":wat::kernel::HandlePool::pop".into(),
                expected: 1,
                got: args.len(),
            },
        )
        .into());
    }
    let (name, rx) = match eval_inner(&args[0], env, sym)?.value_owned() {
        Value::wat__kernel__HandlePool { name, rx } => (name, rx),
        other => {
            return Err(RuntimeError::new(
                args[0].span().clone(),
                RuntimeErrorKind::TypeMismatch {
                    op: ":wat::kernel::HandlePool::pop".into(),
                    expected: "wat::kernel::HandlePool",
                    got: Box::new(ValueSnapshot::of(&other)),
                },
            )
            .into());
        }
    };
    // The sender was dropped at pool construction — recv() returns immediately
    // (either a value or Err on empty). Equivalent to try_recv without the
    // try_recv surface (Stone 214 1b-ii-ε: try_recv annihilated from substrate).
    match rx.recv() {
        Ok(v) => Ok(v),
        Err(_) => Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::MalformedForm {
                head: ":wat::kernel::HandlePool::pop".into(),
                reason: format!(
                    "{}: no handles left to claim (pool drained or mis-counted at construction)",
                    name
                ),
            },
        )
        .into()),
    }
}

/// `(:wat::kernel::HandlePool::finish pool)` — assert the pool is
/// empty and return `:()`. Callers call this at the end of wiring to
/// catch orphaned handles BEFORE any thread runs. If handles remain
/// (an orphan — typically a mis-counted handle budget at
/// construction), returns a MalformedForm error naming the pool and
/// the orphan count. This is the "claim or panic" discipline from
/// FOUNDATION's Pipeline Discipline rule 2.
pub(crate) fn eval_handle_pool_finish(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    if args.len() != 1 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: ":wat::kernel::HandlePool::finish".into(),
                expected: 1,
                got: args.len(),
            },
        )
        .into());
    }
    let (name, rx) = match eval_inner(&args[0], env, sym)?.value_owned() {
        Value::wat__kernel__HandlePool { name, rx } => (name, rx),
        other => {
            return Err(RuntimeError::new(
                args[0].span().clone(),
                RuntimeErrorKind::TypeMismatch {
                    op: ":wat::kernel::HandlePool::finish".into(),
                    expected: "wat::kernel::HandlePool",
                    got: Box::new(ValueSnapshot::of(&other)),
                },
            )
            .into());
        }
    };
    let remaining = rx.len();
    if remaining != 0 {
        return Err(RuntimeError::new(list_span.clone(), RuntimeErrorKind::MalformedForm {
            head: ":wat::kernel::HandlePool::finish".into(),
            reason: format!(
                "{}: {} orphaned handle(s) — deadlock risk (every handle must be claimed before finish)",
                name, remaining
            )
        }).into());
    }
    Ok(Value::Unit)
}

// :wat::kernel::spawn retired in arc 114. The arc-060 SpawnOutcome
// channel pattern lived on inside the arc-114 in-thread satisfier
// (`:wat::kernel::spawn-thread`, itself retired — non-prime IPC
// de-prime, this pass) and `spawn_with_world_into_result` (the
// Process<I,O> in-thread driver from arc 103a). The retired bare-
// spawn impl is gone; the type-checker poisons every call site
// pre-runtime so this layer is unreachable. See arc 114
// INSCRIPTION for the contract retirement. Arc 278's vacate-spawn-
// outcome strike purged the SpawnOutcome/ProgramHandleInner types
// themselves: a locus (`:user::main`) has no meaningful return
// value — it communicates only by channel — so the "spawn a fn,
// get a Value back" chain those types existed to carry had zero
// producers left; its death-reason job was already carried
// structurally by `recv'` -> `Lost[LociDiedError]`.

/// Coerce a `catch_unwind` panic payload to a printable String —
/// same shape Rust's default panic hook does, plus an
/// `AssertionPayload` arm so substrate-raised assertion failures
/// (the structured panic shape `:wat::kernel::assertion-failed!`
/// uses) surface their full message instead of falling through to
/// the generic non-string marker.
///
/// Order tried: `&str` (literal `panic!("...")`); `String`
/// (formatted `panic!("{}", ...)`); `AssertionPayload` (substrate's
/// structured assertion shape); fallback marker.
///
/// Borrows the payload — caller retains ownership for further
/// inspection. `extract_panic_payload` (below) is the
/// owning sibling that takes the box and recovers the
/// AssertionPayload's structured fields when present.
pub(crate) fn format_panic_payload(payload: &Box<dyn std::any::Any + Send>) -> String {
    if let Some(s) = payload.downcast_ref::<&'static str>() {
        return (*s).to_string();
    }
    if let Some(s) = payload.downcast_ref::<String>() {
        return s.clone();
    }
    if let Some(p) = payload.downcast_ref::<crate::assertion::AssertionPayload>() {
        return p.message.clone();
    }
    "panic with non-string payload".to_string()
}

/// Owning extraction. Arc 105c widened the panic-payload extraction
/// to carry both the message string AND the structured
/// `AssertionPayload` (when present) so arc 064's "assert-eq
/// surfaces actual / expected through run-sandboxed" promise
/// survives the substrate-shrinkage cleanup.
///
/// Takes the payload by value so we can `downcast::<T>()` (which
/// transfers ownership and lets us keep the AssertionPayload's
/// owned String fields). On non-AssertionPayload payloads, falls
/// back to formatting via the same logic as `format_panic_payload`.
pub(crate) fn extract_panic_payload(
    payload: Box<dyn std::any::Any + Send>,
) -> (String, Option<crate::assertion::AssertionPayload>) {
    match payload.downcast::<crate::assertion::AssertionPayload>() {
        Ok(boxed) => {
            let p = *boxed;
            (p.message.clone(), Some(p))
        }
        Err(p) => {
            // Not an AssertionPayload — format via the borrow-taking
            // helper. Same string the previous shape produced.
            (format_panic_payload(&p), None)
        }
    }
}

// :wat::kernel::join and :wat::kernel::join-result retired in arc
// 114. Thread/join-result is the canonical replacement;
// Process/join-result handles the forked-program case. The bare
// verbs assumed an :R return through the spawn channel — arc 114
// retires that contract; programs deliver values only through
// their output pipe. Type-checker poison ensures no caller reaches
// this layer.

/// Build a `:wat::kernel::ThreadDiedError::Panic` enum value
/// (arc 060 + arc 105c). Variant carries two fields:
/// `message: String` always populated; `failure: Option<Failure>`
/// populated when the panic was an `AssertionPayload` carrying
/// arc 064's structured actual / expected / location / frames
/// info, `:None` for plain panics.
fn thread_died_error_panic(
    message: String,
    assertion: Option<crate::assertion::AssertionPayload>,
) -> Value {
    let failure_field = match assertion {
        Some(p) => {
            // Build a :wat::kernel::Failure Value::Aggregate(Struct) out of the
            // AssertionPayload's owned fields. Same shape arc 064
            // produced via the now-deleted build_failure helper in
            // src/sandbox.rs.
            Value::Option(Arc::new(Some(failure_value_from_assertion_payload(p))))
        }
        None => Value::Option(Arc::new(None)),
    };
    Value::Enum(Arc::new(EnumValue {
        type_path: ":wat::kernel::LociDiedError".into(),
        variant_name: "Panic".into(),
        names: builtin_enum_variant_names(":wat::kernel::LociDiedError", "Panic"),
        fields: vec![Value::String(Arc::new(message)), failure_field],
    }))
}

/// Convert an [`AssertionPayload`] into a `:wat::kernel::Failure`
/// `Value::Aggregate(Record)`. Field order mirrors the type registration:
/// `(error, frames, actual, expected)`.
/// Arc 293.W.2b — Failure is now Nature::Record (pure EDN data; all fields pure).
///
/// Arc 278 the string-wrap annihilation — the mandatory `error` field carries
/// the raised `:wat::core::Error` STRUCTURALLY. When the payload came from
/// `raise!` (`raised_error = Some(e)`), that error value rides directly. Every
/// other panic (assert-* failures, `expect`, plain panics) has no structured
/// error, so a `:wat::core::Fault` is SYNTHESIZED from the payload's `message`
/// + `location` — honest (a panic IS an error with that message), not fabrication.
fn failure_value_from_assertion_payload(p: crate::assertion::AssertionPayload) -> Value {
    let crate::assertion::AssertionPayload {
        message,
        actual,
        expected,
        location,
        frames,
        // Arc 113 — chain rides on the panic payload but doesn't
        // become part of the Failure record (Failure pre-dates the
        // chain; cascade reconstruction lives one layer up, in
        // join-result).
        upstream_chain: _,
        // Arc 138 F-NAMES-1d — thread_name is for the panic hook render
        // only; it doesn't map to a Failure record field.
        thread_name: _,
        raised_error,
    } = p;
    // The mandatory structured cause: the raised Error verbatim, or a Fault
    // synthesized from the bare message + location.
    let error_field = match raised_error {
        Some(e) => e,
        None => fault_value(message, location),
    };
    let frames_field = Value::Vec(Arc::new(
        frames
            .into_iter()
            .map(value_from_frame_info)
            .collect::<Vec<_>>(),
    ));
    let actual_field = match actual {
        Some(s) => Value::Option(Arc::new(Some(Value::String(Arc::new(s))))),
        None => Value::Option(Arc::new(None)),
    };
    let expected_field = match expected {
        Some(s) => Value::Option(Arc::new(Some(Value::String(Arc::new(s))))),
        None => Value::Option(Arc::new(None)),
    };
    Value::Aggregate(Arc::new(AggregateValue::record(
        "wat::kernel::Failure".into(),
        failure_names(),
        Arc::new(vec![
            error_field,
            frames_field,
            actual_field,
            expected_field,
        ]),
    )))
}

::wat_source_derive::wat_field_names_from!(
    FAILURE_FIELDS,
    "wat/kernel/diagnostics.wat",
    ":wat::kernel::Failure"
);
pub(crate) fn failure_names() -> Arc<Vec<String>> {
    static N: std::sync::OnceLock<Arc<Vec<String>>> = std::sync::OnceLock::new();
    N.get_or_init(|| crate::value::value::names_arc_from_static(FAILURE_FIELDS))
        .clone()
}

/// Arc 278 — build a `:wat::core::Fault` `Value::Aggregate(Record)` from a
/// human message + an optional source location. Field order matches the
/// `:wat::core::Fault` registration (core.wat): `(message, location, causes)`.
/// `location` is a MANDATORY `:wat::kernel::Location` (not `Option`); when the
/// panic carried no span (transport/synthetic failures — disconnected, shutdown,
/// service crash), a synthetic `<runtime>` location marks it honestly. `causes`
/// is an empty `Vector<Error>`. This is the canonical synthesizer for every
/// death that is a bare message rather than a structured `raise!`.
fn fault_value(message: String, location: Option<crate::span::Span>) -> Value {
    let location_value = match location {
        Some(span) => value_from_span(span),
        None => value_from_span(crate::span::Span::new(
            Arc::new("<runtime>".to_string()),
            0,
            0,
        )),
    };
    Value::Aggregate(Arc::new(AggregateValue::record(
        "wat::core::Fault".into(),
        fault_names(),
        Arc::new(vec![
            Value::String(Arc::new(message)),
            location_value,
            Value::Vec(Arc::new(Vec::new())), // causes: empty Vector<Error>
        ]),
    )))
}

/// Arc 278 — read a named field off a record `Value` using the `TypeEnv` to
/// resolve the field's positional index (records store fields positionally;
/// names live only in the registered `AggregateDef`). Returns `None` when the
/// value is not an aggregate, its type is unregistered, or the field is absent.
/// Backs the DERIVED `:wat::kernel::Failure/message` / `Failure/location`
/// accessors (read `error.message` / `error.location`) and `raise!`'s human-message
/// extraction — the same field-by-name lookup `keyword_accessor_record` performs.
fn record_field_by_name(
    v: &Value,
    field: &str,
    types: Option<&crate::types::TypeEnv>,
) -> Option<Value> {
    let Value::Aggregate(agg) = v else {
        return None;
    };
    let types = types?;
    let type_key = format!(":{}", agg.class);
    match types.get(&type_key) {
        Some(crate::types::TypeDef::Aggregate(a)) => {
            let idx = a.field_names().position(|n| n == field)?;
            agg.fields.get(idx).cloned()
        }
        _ => None,
    }
}

/// Convert a `Span` into a `:wat::kernel::Location` `Value::Aggregate(Record)`.
/// Field order: `(file, line, col)`.
/// Arc 293.W.2b — Location is now Nature::Record (pure EDN data).
pub(crate) fn value_from_span(span: crate::span::Span) -> Value {
    Value::Aggregate(Arc::new(AggregateValue::record(
        "wat::kernel::Location".into(),
        location_names(),
        Arc::new(vec![
            Value::String(Arc::new((*span.file).clone())),
            Value::i64(span.line),
            Value::i64(span.col),
        ]),
    )))
}

::wat_source_derive::wat_field_names_from!(
    LOCATION_FIELDS,
    "wat/core.wat",
    ":wat::kernel::Location"
);
pub(crate) fn location_names() -> Arc<Vec<String>> {
    static N: std::sync::OnceLock<Arc<Vec<String>>> = std::sync::OnceLock::new();
    N.get_or_init(|| crate::value::value::names_arc_from_static(LOCATION_FIELDS))
        .clone()
}

/// Convert a `FrameInfo` (wat call-stack frame from the trampoline)
/// into a `:wat::kernel::Frame` `Value::Aggregate(Record)`. Field order matches
/// the arc 016 type registration: `(file, line, symbol)`. The
/// callee path becomes the `symbol` field.
/// Arc 293.W.2b — Frame is now Nature::Record (pure EDN data).
/// Arc 109 — Frame's fields are concrete (non-`Option`): a `FrameInfo` always
/// carries a real span (file/line) and a real callee path (symbol).
fn value_from_frame_info(frame: FrameInfo) -> Value {
    let FrameInfo {
        callee_path,
        call_span,
    } = frame;
    Value::Aggregate(Arc::new(AggregateValue::record(
        "wat::kernel::Frame".into(),
        frame_names(),
        Arc::new(vec![
            Value::String(Arc::new((*call_span.file).clone())),
            Value::i64(call_span.line),
            Value::String(Arc::new(callee_path)),
        ]),
    )))
}

::wat_source_derive::wat_field_names_from!(
    FRAME_FIELDS,
    "wat/kernel/diagnostics.wat",
    ":wat::kernel::Frame"
);
fn frame_names() -> Arc<Vec<String>> {
    static N: std::sync::OnceLock<Arc<Vec<String>>> = std::sync::OnceLock::new();
    N.get_or_init(|| crate::value::value::names_arc_from_static(FRAME_FIELDS))
        .clone()
}

/// Build a `:wat::kernel::ThreadDiedError::RuntimeError(message)`
/// enum value (arc 060).
fn thread_died_error_runtime(message: String) -> Value {
    Value::Enum(Arc::new(EnumValue {
        type_path: ":wat::kernel::LociDiedError".into(),
        variant_name: "RuntimeError".into(),
        names: builtin_enum_variant_names(":wat::kernel::LociDiedError", "RuntimeError"),
        fields: vec![Value::String(Arc::new(message))],
    }))
}

/// Build a `:wat::kernel::LociDiedError::Stopped`
/// (unit variant) enum value (arc 170 Slice A).
/// Produced when the process-wide shutdown signal fires during recv, or
/// (arc 278 send-mirrors-recv) when it fires while a `Sender::send` is
/// polled-blocked waiting for pipe room — the wat-visible variant is
/// `Stopped` (arc-170 intueri cast: nothing on the wat side is "shutting
/// down", a stop was merely requested), while the Rust signal that triggers
/// it keeps its own uniform `shutdown` vocabulary, hence this fn's name.
/// Distinguishable from ChannelDisconnected: the channel partner did
/// NOT drop — the process is stopping. Used by [`loci_died_from_send_error`]
/// (send' side); the recv' side builds its own inline copy in
/// `recv_outcome_shutdown`.
fn thread_died_error_shutdown() -> Value {
    Value::Enum(Arc::new(EnumValue {
        type_path: ":wat::kernel::LociDiedError".into(),
        variant_name: "Stopped".into(),
        names: no_field_names(),
        fields: vec![],
    }))
}

/// `(:wat::kernel::Failure/message f) -> :String` — arc 278 the string-wrap
/// annihilation. DERIVED accessor: reads `error.message` off the Failure's
/// mandatory `:wat::core::Error` field. (`message` is no longer a stored field;
/// storing it alongside `error` would duplicate and could drift — four-questions
/// Fork B.) Every existing `Failure/message` reader keeps working unchanged.
pub(crate) fn eval_failure_message(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::Failure/message";
    let error = failure_error_field(OP, args, env, sym, list_span)?;
    let types = sym.types().map(|a| a.as_ref());
    match record_field_by_name(&error, "message", types) {
        Some(v @ Value::String(_)) => Ok(v),
        _ => Err(RuntimeError::new(
            args[0].span().clone(),
            RuntimeErrorKind::TypeMismatch {
                op: OP.into(),
                expected: "String at :wat::core::Error/message",
                got: Box::new(ValueSnapshot::unavailable(
                    "error has no String message field",
                )),
            },
        )
        .into()),
    }
}

/// `(:wat::kernel::Failure/location f) -> :Option<:wat::kernel::Location>` — arc 278
/// the string-wrap annihilation. DERIVED accessor: reads `error.location` (a
/// mandatory `:wat::kernel::Location` on the error) and wraps it in `Some` to keep
/// the accessor's historic `Option<Location>` return shape.
pub(crate) fn eval_failure_location(
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    const OP: &str = ":wat::kernel::Failure/location";
    let error = failure_error_field(OP, args, env, sym, list_span)?;
    let types = sym.types().map(|a| a.as_ref());
    match record_field_by_name(&error, "location", types) {
        Some(loc @ Value::Aggregate(_)) => Ok(Value::Option(Arc::new(Some(loc)))),
        _ => Err(RuntimeError::new(
            args[0].span().clone(),
            RuntimeErrorKind::TypeMismatch {
                op: OP.into(),
                expected: "Location at :wat::core::Error/location",
                got: Box::new(ValueSnapshot::unavailable("error has no Location field")),
            },
        )
        .into()),
    }
}

/// Shared arity-1 eval + `error`-field extraction for the derived `Failure/*`
/// accessors. Evaluates the single Failure arg and returns its `error` field
/// (the raised `:wat::core::Error`).
fn failure_error_field(
    op: &str,
    args: &[WatAST],
    env: &Environment,
    sym: &SymbolTable,
    list_span: &Span,
) -> Result<Value, EvalBreak> {
    if args.len() != 1 {
        return Err(RuntimeError::new(
            list_span.clone(),
            RuntimeErrorKind::ArityMismatch {
                op: op.into(),
                expected: 1,
                got: args.len(),
            },
        )
        .into());
    }
    let val = eval_inner(&args[0], env, sym)?.value_owned();
    let types = sym.types().map(|a| a.as_ref());
    match record_field_by_name(&val, "error", types) {
        Some(e) => Ok(e),
        None => Err(RuntimeError::new(
            args[0].span().clone(),
            RuntimeErrorKind::TypeMismatch {
                op: op.into(),
                expected: ":wat::kernel::Failure (with an `error` field)",
                got: Box::new(ValueSnapshot::of(&val)),
            },
        )
        .into()),
    }
}

/// Arc 113 slice 1 — wrap a single DiedError Value in a
/// `Vec<DiedError>` chain.
///
/// The Vec is the chain. Head = the immediate peer that died; tail
/// = whatever killed it, transitively. Consumers reach for
/// `(:wat::core::first chain)` to recover the head when they don't
/// care about the trail.
fn single_died_chain(died: Value) -> Value {
    Value::Vec(Arc::new(vec![died]))
}

/// Arc 278 no-hidden-failures — render a THREAD-peer PANIC death as the SAME
/// bare `Vector<LociDiedError>` EDN line the process tier emits from
/// `emit_chain_envelope` (`value_to_edn_with` → `wat_edn::write`), so the
/// parent's [`loci_died_error_from_reason`] bridges it STRUCTURALLY — the raised
/// Fault rides in `Panic.failure` — instead of falling to the opaque string-wrap
/// (which resurrected the arc-278-annihilated string-wrap for a structured
/// `AssertionPayload`). Thread tier now loci-agnostic-equal to the process tier.
pub(crate) fn thread_crash_panic_edn(
    message: String,
    assertion: Option<crate::assertion::AssertionPayload>,
    types: Option<&crate::types::TypeEnv>,
) -> String {
    let chain = single_died_chain(thread_died_error_panic(message, assertion));
    let edn = crate::edn_shim::value_to_edn_with(&chain, types);
    wat_edn::write(&edn)
}

/// Arc 278 no-hidden-failures — the RuntimeError sibling of
/// [`thread_crash_panic_edn`]. Mirrors the process tier's
/// `process_died_error_runtime_value`: the RuntimeError crosses the wire as
/// structured `to_wire_edn` (its `:message`/`:location`/`:causes` floor), NOT
/// `re.to_string()` prose, wrapped in the same bare `Vector<LociDiedError>` line.
pub(crate) fn thread_crash_runtime_edn(
    re: &RuntimeError,
    types: Option<&crate::types::TypeEnv>,
) -> String {
    let chain = single_died_chain(thread_died_error_runtime(crate::to_edn::to_wire_edn(re)));
    let edn = crate::edn_shim::value_to_edn_with(&chain, types);
    wat_edn::write(&edn)
}

/// Arc 113 slice 2 — conj a fresh DiedError onto the FRONT of an
/// existing chain (or build a singleton when no upstream exists).
///
/// Cascade semantics: when `result::expect` panics on an Err that
/// carried a chain, that chain rides through the panic on the
/// `AssertionPayload`. The spawn driver's catch_unwind reads it
/// here and pushes THIS thread's death (`fresh`) onto the head of
/// the inherited chain. Future joiners walking from the front see
/// the death-chain in causality order: head = the thread the
/// joiner waited on; second = whoever killed it; … last = the
/// originating cause.
fn conj_died_chain(fresh: Value, upstream: Option<Vec<Value>>) -> Value {
    let mut chain = vec![fresh];
    if let Some(tail) = upstream {
        chain.extend(tail);
    }
    Value::Vec(Arc::new(chain))
}

/// Cross-module sibling of [`conj_died_chain`] for `src/fork.rs`'s
/// child-branch panic emission (arc 113 slice 3 — chain rendered
/// to stderr as EDN). Renames-but-otherwise-identical so the
/// fork-side call site reads naturally; the `_value` suffix signals
/// "produces a runtime Value" the way the parallel
/// `process_died_error_panic_value` does.
pub(crate) fn conj_died_chain_value(fresh: Value, upstream: Option<Vec<Value>>) -> Value {
    conj_died_chain(fresh, upstream)
}

/// Build a `:wat::kernel::ProcessDiedError::Panic` enum value
/// (arc 112). Sibling of `thread_died_error_panic` for the
/// Process<I,O> subject. Same payload shape; the type_path
/// distinguishes them at runtime + at the type-checker.
fn process_died_error_panic(
    message: String,
    assertion: Option<crate::assertion::AssertionPayload>,
) -> Value {
    let failure_field = match assertion {
        Some(p) => Value::Option(Arc::new(Some(failure_value_from_assertion_payload(p)))),
        None => Value::Option(Arc::new(None)),
    };
    Value::Enum(Arc::new(EnumValue {
        type_path: ":wat::kernel::LociDiedError".into(),
        variant_name: "Panic".into(),
        names: builtin_enum_variant_names(":wat::kernel::LociDiedError", "Panic"),
        fields: vec![Value::String(Arc::new(message)), failure_field],
    }))
}

/// Cross-module sibling of [`process_died_error_panic`] for
